import json
import re
from docx import Document

def fill_offer_letter(template_path, data_path, output_path):
    with open(data_path, 'r') as f:
        data = json.load(f)

    doc = Document(template_path)

    # 1. Handle Conditional Sections
    # We'll support markers being in separate paragraphs
    relocation_status = data.get('RELOCATION_PACKAGE', 'No') == 'Yes'

    start_marker = '{{IF_RELOCATION}}'
    end_marker = '{{END_IF_RELOCATION}}'

    paras_to_remove = []
    in_conditional = False

    # Track the state and markers
    found_start = False
    found_end = False

    # First pass: find and handle markers
    for i, para in enumerate(doc.paragraphs):
        text = para.text

        if start_marker in text:
            found_start = True
            in_conditional = True
            # Remove marker from paragraph
            para.text = para.text.replace(start_marker, '')
            # If nothing left and we are removing content, mark for removal
            if not relocation_status and not para.text.strip():
                paras_to_remove.append(i)
            continue

        if end_marker in text:
            found_end = True
            in_conditional = False
            # Remove marker from paragraph
            para.text = para.text.replace(end_marker, '')
            # If nothing left and we are removing content, mark for removal
            if not relocation_status and not para.text.strip():
                paras_to_remove.append(i)
            continue

        if in_conditional and not relocation_status:
            paras_to_remove.append(i)

    # Remove paragraphs in reverse order to maintain indices
    for idx in sorted(paras_to_remove, reverse=True):
        p = doc.paragraphs[idx]._element
        p.getparent().remove(p)
        p._p = p._element = None

    # 2. Replace Placeholders in all paragraphs, tables, and headers/footers
    def replace_placeholders(text):
        pattern = r'\{\{([A-Z_]+)\}\}'
        matches = re.findall(pattern, text)
        for key in matches:
            if key in data:
                text = text.replace('{{' + key + '}}', str(data[key]))
        return text

    def process_paragraph(para):
        if not para.text:
            return

        full_text = para.text
        new_text = replace_placeholders(full_text)

        if new_text != full_text:
            if para.runs:
                # Preserve formatting of the first run
                para.runs[0].text = new_text
                for run in para.runs[1:]:
                    run.text = ''
            else:
                para.text = new_text

    # Main paragraphs
    for para in doc.paragraphs:
        process_paragraph(para)

    # Tables
    def process_table(table):
        for row in table.rows:
            for cell in row.cells:
                for para in cell.paragraphs:
                    process_paragraph(para)
                for nested_table in cell.tables:
                    process_table(nested_table)

    for table in doc.tables:
        process_table(table)

    # Headers/Footers
    for section in doc.sections:
        for para in section.header.paragraphs:
            process_paragraph(para)
        for para in section.footer.paragraphs:
            process_paragraph(para)

    doc.save(output_path)

if __name__ == "__main__":
    fill_offer_letter('offer_letter_template.docx', 'employee_data.json', 'offer_letter_filled.docx')

